sentence = input("enter your sentence ")

words_in_order = [[]]
for i in sentence:
  if i == ' ':
    words_in_order.append([])
  else:
    words_in_order[-1].append(i)

reversed_words = ""
for i in words_in_order[::-1]:
  word = ""
  for j in i:
    word += j
  word += " "
  reversed_words += word

print(reversed_words)
